test.use({viewport:{width:1440,height:900},actionTimeout:8000,navigationTimeout:15000});
const pageErrors=new WeakMap<Page,string[]>(),consoleRows=new WeakMap<Page,unknown[]>();
function listen(page:Page){if(pageErrors.has(page))return;const errors:string[]=[],rows:unknown[]=[];pageErrors.set(page,errors);consoleRows.set(page,rows);page.on('pageerror',e=>errors.push(e.message));page.on('console',e=>{if(e.type()==='warning'||e.type()==='error')rows.push({type:e.type(),text:e.text()});});}
test.beforeEach(async({page})=>listen(page));
test.afterEach(async({page,context},info)=>{for(const p of context.pages())if(!p.isClosed())await p.evaluate(()=>{const w=window as any;w.__narrativeReleaseWrite?.();w.__narrativeRestorePut?.();w.__narrativeObserver?.disconnect();w.__narrativeRestoreRead?.();w.__narrativeSender?.close();});await info.attach('narrative-browser-errors',{body:JSON.stringify({errors:pageErrors.get(page),console:consoleRows.get(page)}),contentType:'application/json'});expect(pageErrors.get(page)).toEqual([]);});
async function database(page:Page){return page.evaluate(()=>new Promise<any>((resolve,reject)=>{const request=indexedDB.open('chenyuan-playable-v1');request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,names=[...db.objectStoreNames],tx=db.transaction(names,'readonly'),rows:any={};for(const name of names){rows[name]=[];const q=tx.objectStore(name).openCursor();q.onsuccess=()=>{if(q.result){rows[name].push({key:q.result.key,value:q.result.value});q.result.continue();}};}tx.oncomplete=()=>{db.close();resolve(rows);};tx.onabort=()=>{db.close();reject(tx.error);};};}));}
async function load(page:Page,game:any,virtual=true){await nativeHooks(page);if(virtual)await useJourneyClock(page);await page.goto('/');await expect(page.getByLabel('导入已有存档',{exact:true})).toBeEnabled({timeout:15000});await page.getByLabel('导入已有存档',{exact:true}).setInputFiles({name:'lawful-art05-narrative.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(game))});if(virtual)await finishJourneyClock(page);await expect(page.getByTestId('save-status')).toHaveText('已保存');return snapshot(page);}
async function unchanged(page:Page,game:any,a:any,raw:any){const rows=await database(page),state=rows['full-state'];expect(state.find((r:any)=>r.key==='current')?.value).toEqual(game);expect(state.find((r:any)=>r.key==='activity')?.value??null).toEqual(a);expect(rows).toEqual(raw);}
function pendingStory(){const d=driver();d.go('sect');const event=availableEvents(d.game)[0];expect(event).toBeTruthy();d.doAction({type:'EVENT',event:event.id});return d;}
async function menuGeometry(page:Page,dialogId:string,rackSelector:string,people=false){
 const g=await page.getByTestId(dialogId).evaluate((dialog,{rackSelector})=>{
  const visible=(n:Element)=>!!n.getClientRects().length,rect=(n:Element)=>{const r=n.getBoundingClientRect();return{left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,height:r.height};},inside=(a:any,b:any)=>a.left>=b.left-.5&&a.right<=b.right+.5&&a.top>=b.top-.5&&a.bottom<=b.bottom+.5,overlap=(a:any,b:any)=>a.left<b.right-.5&&a.right>b.left+.5&&a.top<b.bottom-.5&&a.bottom>b.top+.5;
  const racks=[...dialog.querySelectorAll(rackSelector)].filter(visible),rack=racks[0],entries=rack?[...rack.querySelectorAll('button')]:[],clashes:any[]=[];
  for(let i=0;i<entries.length;i++)for(let j=i+1;j<entries.length;j++)if(overlap(rect(entries[i]),rect(entries[j])))clashes.push({a:entries[i].getAttribute('data-testid'),b:entries[j].getAttribute('data-testid')});
  const controls=[...dialog.querySelectorAll<HTMLElement>('button')].filter(visible).map(n=>{const r=rect(n),hit=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2),parents:any[]=[];let parent=n.parentElement;while(parent){parents.push({class:parent.className,rect:rect(parent),contained:inside(r,rect(parent))});if(parent===dialog)break;parent=parent.parentElement;}return{id:n.getAttribute('data-testid'),rect:r,insideViewport:r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight,hit:!!hit&&(n===hit||n.contains(hit)),parents,clipped:n.scrollWidth>n.clientWidth+1||n.scrollHeight>n.clientHeight+1,text:[...n.querySelectorAll<HTMLElement>('strong,small')].map(t=>({tag:t.tagName,text:t.textContent,font:parseFloat(getComputedStyle(t).fontSize),contained:inside(rect(t),r),clipped:t.scrollWidth>t.clientWidth+1||t.scrollHeight>t.clientHeight+1}))};});
  return{dialog:rect(dialog),rackCount:racks.length,rackContained:!!rack&&inside(rect(rack),rect(dialog)),entryCount:entries.length,visibleEntries:entries.filter(visible).length,clashes,controls};
 },{rackSelector});
 await test.info().attach('legacy-'+dialogId+'-surface-'+test.info().attachments.length,{body:JSON.stringify(g),contentType:'application/json'});
 expect(g.rackCount,dialogId+' actual rack').toBe(1);expect(g.rackContained,dialogId+' rack in dialog').toBe(true);if(people)expect(g.entryCount,dialogId+' all four people').toBe(4);else expect(g.entryCount,dialogId+' available choices').toBeGreaterThan(0);expect(g.visibleEntries,dialogId+' every entry visible').toBe(g.entryCount);expect(g.clashes,dialogId+' entry overlap').toEqual([]);
 for(const c of g.controls){expect(c.rect.width,c.id??'').toBeGreaterThanOrEqual(44);expect(c.rect.height,c.id??'').toBeGreaterThanOrEqual(44);expect(c.insideViewport,c.id??'').toBe(true);expect(c.hit,c.id??'').toBe(true);expect(c.clipped,c.id??'').toBe(false);for(const parent of c.parents)expect(parent.contained,(c.id??'')+' in '+parent.class).toBe(true);for(const t of c.text){expect(t.font,t.text??'').toBeGreaterThanOrEqual(t.tag==='STRONG'?18:14);expect(t.contained,t.text??'').toBe(true);expect(t.clipped,t.text??'').toBe(false);}}
}
async function selectPerson(page:Page,testId:string){await page.getByTestId('fate-people-open').click();await expect(page.getByTestId('fate-people-dialog')).toBeVisible();await menuGeometry(page,'fate-people-dialog','.encounter-name-rack',true);await page.getByTestId(testId).click();await expect(page.getByTestId('fate-people-dialog')).not.toBeVisible();}
async function selectSignature(page:Page,testId:string){await page.getByTestId('response-choices-open').click();await expect(page.getByTestId('response-choices-dialog')).toBeVisible();await menuGeometry(page,'response-choices-dialog','.response-sign-rack');await page.getByTestId(testId).click();await expect(page.getByTestId('response-choices-dialog')).not.toBeVisible();}
async function openManagement(page:Page){await page.getByTestId('life-manage-open').click();await expect(page.getByTestId('life-manage-dialog')).toBeVisible();}
async function currentStory(page:Page){await page.getByTestId('tab-0').click();await page.getByTestId('hub-current').getByRole('button',{name:'继续当前遭遇',exact:true}).click();await expect(page.getByTestId('narrative-catalogue')).toBeVisible();}
async function readAll(page:Page,panelId:string){const panel=page.getByTestId(panelId),prev=panel.getByTestId('catalogue-prev'),next=panel.getByTestId('catalogue-next'),rows=new Map<string,string>();for(let n=0;n<350&&await prev.isEnabled();n++)await prev.click();for(let n=0;n<350;n++){const reading=panel.locator('.reading-text:visible').first(),row=await reading.evaluate(n=>{const p=n.querySelector('p')!,r=p.getBoundingClientRect(),box=n.getBoundingClientRect(),canvas=n.closest('.book-canvas')!.getBoundingClientRect();return{key:n.getAttribute('data-page-key'),text:p.textContent??'',font:parseFloat(getComputedStyle(p).fontSize),top:r.top,bottom:r.bottom,left:r.left,right:r.right,box:{top:box.top,bottom:box.bottom,left:box.left,right:box.right},canvas:{top:canvas.top,bottom:canvas.bottom,left:canvas.left,right:canvas.right}};});expect(row.font).toBeGreaterThanOrEqual(18);expect(row.top).toBeGreaterThanOrEqual(Math.max(row.box.top,row.canvas.top)-.5);expect(row.bottom).toBeLessThanOrEqual(Math.min(row.box.bottom,row.canvas.bottom)+.5);expect(row.left).toBeGreaterThanOrEqual(Math.max(row.box.left,row.canvas.left)-.5);expect(row.right).toBeLessThanOrEqual(Math.min(row.box.right,row.canvas.right)+.5);if(row.key===null){expect(row.text).toBe('暂无其他选择记录；不补写交情。');expect(await next.isDisabled()).toBe(true);return rows;}rows.set(row.key!,(rows.get(row.key!)??'')+row.text);if(await next.isDisabled())return rows;await next.click();}throw new Error('Full narrative reading did not end');}
async function picture(page:Page,info:TestInfo,name:string){await expect.poll(()=>page.evaluate(()=>{const app=document.querySelector<HTMLElement>('.app-shell'),alerts=app?.querySelector<HTMLElement>('.stage-alerts');if(!app?.classList.contains('immersive-stage')||!alerts)return true;const h=alerts.getBoundingClientRect().height,n=parseFloat(app.style.getPropertyValue('--notice-height'));return Number.isFinite(n)&&Math.abs(n-(h?h+8:0))<=.5;}),{timeout:8000}).toBe(true);const g=await page.evaluate(()=>{const visible=(n:Element)=>!!n.getClientRects().length,rect=(n:Element)=>{const r=n.getBoundingClientRect();return{left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,height:r.height};},nav=document.getElementById('primary-navigation')?rect(document.getElementById('primary-navigation')!):{top:innerHeight},modal=document.querySelector('dialog[open]');return{height:document.documentElement.scrollHeight,width:document.documentElement.scrollWidth,navTop:nav.top,stages:[...document.querySelectorAll<HTMLElement>('[data-testid=encounter-table],[data-testid=response-table],[data-testid=life-scroll]')].filter(visible).map(n=>{const r=rect(n),p=rect(n.parentElement!),c=getComputedStyle(n);return{id:n.getAttribute('data-testid'),rect:r,parent:p,layout:{display:c.display,rows:c.gridTemplateRows,columns:c.gridTemplateColumns,minHeight:c.minHeight,overflow:c.overflow},contained:r.left>=p.left-.5&&r.right<=p.right+.5&&r.top>=p.top-.5&&r.bottom<=p.bottom+.5};}),body:[...document.querySelectorAll<HTMLElement>('.reading-text p')].filter(visible).map(n=>{const r=rect(n),p=rect(n.parentElement!);return{text:n.textContent,font:parseFloat(getComputedStyle(n).fontSize),rect:r,parent:p,contained:r.left>=p.left-.5&&r.right<=p.right+.5&&r.top>=p.top-.5&&r.bottom<=p.bottom+.5&&r.bottom<=nav.top,clipped:n.scrollWidth>n.clientWidth||n.scrollHeight>n.clientHeight};}),controls:[...document.querySelectorAll<HTMLElement>(modal?'dialog[open] button,dialog[open] input,dialog[open] select':'main button,main input,main select,#primary-navigation button,.error-banner button')].filter(visible).map(n=>{const r=rect(n),hit=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);return{id:n.getAttribute('data-testid')??n.textContent,rect:r,inside:r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=(modal||n.closest('#primary-navigation')?innerHeight:nav.top),hit:n.matches(':disabled')||!!hit&&(n===hit||n.contains(hit)),interceptor:hit?{tag:hit.tagName,id:hit.getAttribute('data-testid'),class:hit.className}:null};})};});await info.attach(name+'-geometry',{body:JSON.stringify(g),contentType:'application/json'});await page.screenshot({path:info.outputPath(name+'.png')});await objectGeometry(page,info,name);expect(g.height).toBeLessThanOrEqual(900);expect(g.width).toBeLessThanOrEqual(1440);for(const s of g.stages)expect(s.contained,s.id+' in actual parent').toBe(true);for(const p of g.body){expect(p.font,p.text??'').toBeGreaterThanOrEqual(18);expect(p.contained,p.text??'').toBe(true);expect(p.clipped,p.text??'').toBe(false);}for(const c of g.controls){expect(c.rect.height,c.id??'').toBeGreaterThanOrEqual(44);expect(c.inside,c.id??'').toBe(true);expect(c.hit,c.id??'').toBe(true);}}

test('ART05-A1 all four factual people keep their complete known and future readings in a readonly encounter object',async({page},info)=>{
 const before=await load(page,feedbackExamples().actions.get('START_TRIAL')!.before),raw=await database(page);await page.getByTestId('tab-3').click();for(const person of getRelationships(before)){await selectPerson(page,'fate-person-'+person.id);const rows=await readAll(page,'fate-catalogue');expect(rows.get('summary')).toBe(person.summary);for(const f of person.facts)expect(rows.get(f.id)).toBe(f.text);if(person.next){expect(rows.get('next')).toBe(C.locations[person.next.location].name+' · '+C.realms[person.next.min].name+'起。'+(person.next.unlocked?(person.next.view?.body??''):'待相应境界后再访，不会自动触发或补发物资。'));for(const o of person.next.view?.options??[])expect(rows.get('option-'+o.id)).toBe(o.detail);}else expect(rows.get('complete')).toBe('实际选择记录仍保留，不补写未发生的来往。');await picture(page,info,'person-'+person.id+'-factual-object');await unchanged(page,before,null,raw);}expect(getRelationships(before).map(p=>p.id).sort()).toEqual(['lu','pei','shen','yan']);await expect(page.getByTestId('encounter-table')).toBeVisible();
});

test('ART05-A2 complete responses question answers and both endings remain readonly preselected objects until their original confirmation',async({browser},info)=>{
 for(const type of ['DECIDE','ANSWER_TRIAL','END']as const){const context=await browser.newContext({baseURL:'http://127.0.0.1:4173',viewport:{width:1440,height:900}}),p=await context.newPage();listen(p);try{const before=await load(p,feedbackExamples().actions.get(type)!.before),raw=await database(p),model=narrativeFor(before)!;await currentStory(p);const body=await readAll(p,'narrative-catalogue');expect(body.get('body')).toBe(model.body);await p.getByTestId('story-show-choices').click();for(const choice of model.choices){await selectSignature(p,'story-select-'+choice.id);await expect(p.getByTestId(choice.id)).toBeVisible();await p.getByRole('button',{name:'查看'+choice.label+'的代价与结果',exact:true}).click();await expect(p.getByRole('dialog',{name:choice.label,exact:true})).toBeVisible();await unchanged(p,before,null,raw);await p.getByRole('button',{name:'关闭选择详情',exact:true}).click();await picture(p,info,type+'-readonly-'+choice.id);}await expect(p.getByTestId('response-table')).toBeVisible();await p.getByTestId('story-mode-memory').click();const memory=await readAll(p,'narrative-catalogue');for(const source of model.memories)expect(memory.get(source.key)).toBe(source.text);await unchanged(p,before,null,raw);expect(pageErrors.get(p)).toEqual([]);}finally{await info.attach(type+'-browser-errors',{body:JSON.stringify({errors:pageErrors.get(p),console:consoleRows.get(p)}),contentType:'application/json'});await context.close();}}
});

test('ART05-A3 the factual life scroll keeps every character in all four chapters and exports without sealing or writing Game',async({page},info)=>{
 const before=await load(page,feedbackExamples().actions.get('END')!.before),raw=await database(page);await page.getByTestId('hub-life').click();for(const group of ['life','training','decisions','seal']){await page.getByTestId('life-mode-'+group).click();const rows=await readAll(page,'life-panel');for(const source of lifeReadings(before).filter(r=>r.group===group))expect(rows.get(source.key),source.key).toBe(source.text);await picture(page,info,'life-scroll-'+group);await unchanged(page,before,null,raw);}await expect(page.getByTestId('life-scroll')).toBeVisible();const download=page.waitForEvent('download');await openManagement(page);await page.getByTestId('export-life').click();const stream=await(await download).createReadStream(),chunks:Buffer[]=[];for await(const chunk of stream!)chunks.push(chunk);expect(Buffer.concat(chunks).toString('utf8')).toBe(exportLifeText(before));await unchanged(page,before,null,raw);
});

const nativeReady=new WeakSet<Page>();
async function nativeHooks(page:Page){if(nativeReady.has(page))return;nativeReady.add(page);await page.addInitScript(()=>{
 const w=window as any,open=IDBFactory.prototype.open,put=IDBObjectStore.prototype.put,Native=BroadcastChannel;w.__narrativeWrites=[];
 IDBFactory.prototype.open=function(...args:any[]){const r=Reflect.apply(open,this,args);if(args[0]==='chenyuan-playable-v1')r.addEventListener('success',()=>{if(!w.__narrativePrimaryDB)w.__narrativePrimaryDB=r.result;});return r;};
 IDBObjectStore.prototype.put=function(v:any,k?:IDBValidKey){if(this.transaction.db.name==='chenyuan-playable-v1'&&this.name==='full-state'&&k==='current')w.__narrativeWrites.push({wall:Date.now(),mono:performance.now(),game:structuredClone(v)});return put.call(this,v,k!);};
 w.BroadcastChannel=new Proxy(Native,{construct(C,args){const c=Reflect.construct(C,args);if(args[0]==='chenyuan-full-progress')c.addEventListener('message',()=>w.__narrativeBC=(w.__narrativeBC??0)+1);return c;}});
});}
const resultsSelector='[data-testid=encounter-result],[data-testid=response-result],[data-testid=life-scroll-result]';
async function observe(page:Page){await page.evaluate(selector=>{const w=window as any,seen=new WeakMap<Element,string>(),rows:any[]=[];function collect(root:Node){if(!(root instanceof Element))return;for(const n of root.matches(selector)?[root]:root.querySelectorAll(selector)){const seq=n.getAttribute('data-sequence');if(seq&&seen.get(n)!==seq){seen.set(n,seq);rows.push({id:n.getAttribute('data-testid'),sequence:seq,text:n.textContent,person:n.closest('[data-person]')?.getAttribute('data-person'),action:document.querySelector('[data-testid^=story-select-][aria-pressed=true]')?.getAttribute('data-testid'),wall:Date.now()});}}}const o=new MutationObserver(cs=>{for(const c of cs){if(c.type==='attributes')collect(c.target);else for(const n of c.addedNodes)collect(n);}});o.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['data-sequence']});w.__narrativeObserver=o;w.__narrativeEffects=rows;},resultsSelector);}
async function effects(page:Page){return page.evaluate(()=>(window as any).__narrativeEffects??[]);}
async function noEffect(page:Page){await expect(page.locator(resultsSelector)).toHaveCount(0);}
async function cold(page:Page,id:string){const object=page.getByTestId(id);await expect(object).toHaveAttribute('data-working','false');for(const ink of await object.locator('.narrative-object-ink').all())expect(await ink.evaluate(n=>(n as HTMLElement).style.getPropertyValue('--ink-progress'))).toBe('0%');await expect(object.locator('.narrative-object-saved')).toHaveCount(0);}
async function clearances(page:Page,info:TestInfo,name:string){const g=await page.evaluate(selector=>{const vis=(n:Element)=>!!n.getClientRects().length,r=(n:Element)=>{const x=n.getBoundingClientRect();return{left:x.left,right:x.right,top:x.top,bottom:x.bottom};},hit=(a:any,b:any)=>a.left<b.right&&a.right>b.left&&a.top<b.bottom&&a.bottom>b.top;const copy=[...document.querySelectorAll('.reading-text,.choice-card')].filter(vis).map(r),controls=[...document.querySelectorAll('main button,#primary-navigation button')].filter(vis).map(r);return[...document.querySelectorAll(selector)].filter(vis).map(n=>{const b=r(n),p=r(n.closest('.book-canvas')!);return{id:n.getAttribute('data-testid'),rect:b,parent:p,contained:b.left>=p.left-.5&&b.right<=p.right+.5&&b.top>=p.top-.5&&b.bottom<=p.bottom+.5,clashes:[...copy,...controls].filter(x=>hit(b,x)),font:parseFloat(getComputedStyle(n).fontSize),opacity:getComputedStyle(n).opacity};});},resultsSelector);await info.attach(name+'-result-clearance',{body:JSON.stringify(g),contentType:'application/json'});for(const row of g){expect(row.contained,row.id??'').toBe(true);expect(row.clashes,row.id??'').toEqual([]);expect(row.font).toBeGreaterThanOrEqual(14);expect(row.opacity).toBe('1');}}
async function begin(page:Page,confirm='milestone-confirm',native=false){await page.getByTestId(confirm).click();await expect.poll(async()=>(await activity(page))?.status).toBe('running');const a=await activity(page);expect(a.version).toBe(7);expect(a.completedCycles).toBe(0);await expect(page.locator('[data-testid=training-activity][data-running=true][data-generation="'+a.generation+'"]')).toBeVisible();if(native){const first=await page.getByTestId('training-countdown').innerText(),remaining=parseFloat(first),live=await activity(page);expect(live).toMatchObject({id:a.id,runId:a.runId,generation:a.generation,status:'running',nextCommand:a.nextCommand});expect(first).toMatch(/^\d+\.\d 秒$/);expect(remaining).toBeGreaterThan(0);expect(remaining).toBeLessThanOrEqual(a.cycleMs/1000);await test.info().attach('native-first-countdown',{body:JSON.stringify({first,remainingSeconds:remaining,totalMs:a.cycleMs,activityId:a.id,runId:a.runId,generation:a.generation,status:live.status,startedAt:a.startedAt,dueAt:a.dueAt,boundary:'First actual running observation after acceptance; native clock keeps advancing.'}),contentType:'application/json'});}else await expect(page.getByTestId('training-countdown')).toHaveText((a.cycleMs/1000).toFixed(1)+' 秒');return a;}
async function receipt(page:Page,a:any,before:any){const rows=(await database(page))['full-receipts'].filter((r:any)=>r.key===a.runId+':'+a.nextCommand.commandId);expect(rows).toHaveLength(1);const expected=resolve(before,a.nextCommand),value=rows[0].value;expect(value.command).toEqual(a.nextCommand);expect(value.result).toEqual(expected.result);expect(value.proof.activityBefore).toEqual(a);expect(value.proof.stateAfter).toEqual(expected.nextState);expect(value.proof.resolvedAt).toBeGreaterThanOrEqual(a.dueAt);expect(value.activity).toEqual(completeActivity(expected.nextState,a,expected.result,{commandId:a.nextCommand.commandId,now:value.proof.resolvedAt}));return rows[0];}
async function tick(page:Page,a:any,before:any){const left=await page.evaluate(due=>due-Date.now(),a.dueAt);expect(left).toBeGreaterThan(0);await page.clock.fastForward(left-1);expect(await snapshot(page)).toEqual(before);expect((await database(page))['full-receipts'].filter((r:any)=>r.key===a.runId+':'+a.nextCommand.commandId)).toHaveLength(0);await page.clock.fastForward(1);await expect.poll(async()=>(await activity(page))?.completedCycles).toBe(1);const after=await snapshot(page);expect(after).toEqual(advance(before,a.nextCommand));expect((await activity(page)).status).toBe('stopped');await receipt(page,a,before);await page.clock.runFor(50);return after;}
async function events(page:Page,id:string){await page.getByTestId('tab-3').click();await page.getByTestId('fate-mode-events').click();const panel=page.getByTestId('fate-catalogue'),next=panel.getByTestId('catalogue-next'),prev=panel.getByTestId('catalogue-prev');for(let i=0;i<30&&await prev.isEnabled();i++)await prev.click();for(let i=0;i<30&&!await page.getByTestId('event-'+id).isVisible();i++){expect(await next.isEnabled()).toBe(true);await next.click();}await expect(page.getByTestId('event-'+id)).toBeVisible();}
function tradeStory(){const d=driver('trade','sword');d.realm();d.funds(100);d.go('sect');d.doAction({type:'EVENT',event:'shen_return'});return d;}
async function respond(page:Page,id='bargain'){await currentStory(page);await page.getByTestId('story-show-choices').click();await selectSignature(page,'story-select-decide-'+id);await page.getByTestId('decide-'+id).click();await expect(page.getByTestId('milestone-review')).toBeVisible();}
async function ending(page:Page,id='transmit'){await currentStory(page);await page.getByTestId('story-show-choices').click();await selectSignature(page,'story-select-ending-'+id);await page.getByTestId('ending-'+id).click();await expect(page.getByTestId('ascension-confirmation')).toBeVisible();}
async function lifeEnd(page:Page,id='RETIRE'){await page.getByTestId('hub-life').click();await page.getByTestId('life-mode-seal').click();await openManagement(page);await page.getByTestId(id==='RETIRE'?'retire':'end-life').click();await expect(page.getByTestId('life-confirmation')).toBeVisible();}
async function holdWrite(page:Page){await page.evaluate(()=>new Promise<void>((resolve,reject)=>{const q=indexedDB.open('chenyuan-playable-v1');q.onerror=()=>reject(q.error);q.onsuccess=()=>{const db=q.result,tx=db.transaction('full-state','readwrite');let keep=true,ready=false;(window as any).__narrativeReleaseWrite=()=>keep=false;const read=()=>{const r=tx.objectStore('full-state').get('current');r.onsuccess=()=>{(window as any).__narrativeHeldGame=r.result;if(!ready){ready=true;resolve();}if(keep)read();};};read();tx.oncomplete=()=>db.close();tx.onabort=()=>{db.close();reject(tx.error);};};}));}
async function quota(page:Page,acceptance:boolean){await page.evaluate(acceptance=>{const w=window as any,put=IDBObjectStore.prototype.put;w.__narrativeRestorePut=()=>IDBObjectStore.prototype.put=put;IDBObjectStore.prototype.put=function(v:any,k?:IDBValidKey){if(this.transaction.db.name==='chenyuan-playable-v1'&&(acceptance?this.name==='full-receipts'&&v?.input?.kind==='START':this.name==='full-state'&&k==='current')){w.__narrativeRejected={key:k,value:structuredClone(v)};w.__narrativeRestorePut();throw new DOMException('ART05 native '+(acceptance?'arrangement':'cycle')+' quota','QuotaExceededError');}return put.call(this,v,k!);};},acceptance);}
async function replayFree(page:Page,after:any){const saved=await database(page);await page.clock.fastForward(120000);expect(await snapshot(page)).toEqual(after);expect(await database(page)).toEqual(saved);await noEffect(page);}

for(const [number,kind,period]of [[4,'visit',6000],[5,'response',6000],[6,'ending',12000]]as const)test('ART05-A'+number+' real '+kind+' waits its complete '+period+'ms cycle and saves the exact whole Game once',async({page},info)=>{
 let fixture:any,confirmation='milestone-confirm';if(kind==='visit'){const d=driver();d.go('sect');fixture=d.game;}else fixture=kind==='response'?tradeStory().game:feedbackExamples().actions.get('END')!.before;
 const before=await load(page,fixture,false);if(kind==='visit'){await events(page,'lu_intro');await page.getByTestId('event-lu_intro').click();}else if(kind==='response')await respond(page);else{await ending(page);confirmation='ascension-confirm';}const raw=await database(page);await picture(page,info,kind+'-real-confirmation');await unchanged(page,before,null,raw);await observe(page);const a=await begin(page,confirmation,true),started=await page.evaluate(()=>({wall:Date.now(),mono:performance.now()}));expect(a.cycleMs).toBe(period);const local=kind==='visit'?'encounter-clock':kind==='response'?'response-clock':'life-scroll-clock';
 // END is still on its response object before the committed handoff to the life scroll.
 await expect(page.getByTestId(kind==='ending'?'response-clock':local)).toBeVisible();const first=await page.getByTestId('training-countdown').innerText();await expect.poll(async()=>parseFloat(await page.getByTestId('training-countdown').innerText())).toBeLessThan(parseFloat(first));expect(await snapshot(page)).toEqual(before);await noEffect(page);await picture(page,info,kind+'-real-running');await expect.poll(async()=>(await activity(page))?.completedCycles,{timeout:period+10000}).toBe(1);const after=await snapshot(page);expect(after).toEqual(advance(before,a.nextCommand));const writes=await page.evaluate(()=>(window as any).__narrativeWrites),commits=writes.filter((r:any)=>r.game.core.runId===before.core.runId&&r.game.core.revision===before.core.revision+1);expect(commits).toHaveLength(1);expect(commits[0].wall).toBeGreaterThanOrEqual(a.dueAt);expect((await activity(page)).status).toBe('stopped');await receipt(page,a,before);await expect.poll(()=>page.locator(resultsSelector).count()).toBe(1);await clearances(page,info,kind+'-real-saved');await picture(page,info,kind+'-real-saved');
 if(kind==='visit'){expect(after.core.world.location).toBe(before.core.world.location);expect(after.choices).toEqual(before.choices);expect(after.core.activeEvent?.id).toBe('lu_intro');expect(after.core.inventory).toEqual(before.core.inventory);}else if(kind==='response'){expect(after.core.player.stones).toBe(before.core.player.stones-18);expect(after.core.inventory.healing_pill).toBe(before.core.inventory.healing_pill+1);expect(after.choices.shen_return).toBe('bargain');}else{expect(after.status).toBe('ascended');expect(after.ending).toBe('transmit');expect(after.core.runId).toBe(before.core.runId);await expect(page.getByTestId('life-scroll')).toHaveAttribute('data-sealed','true');}expect(new Set((await effects(page)).map((r:any)=>r.sequence)).size).toBe(1);await info.attach(kind+'-real-cycle-proof',{body:JSON.stringify({started,ended:await page.evaluate(()=>({wall:Date.now(),mono:performance.now()})),activity:a,commits,effects:await effects(page),after}),contentType:'application/json'});
});

test('ART05-A7 the other ending retirement and lifespan seal only their selected factual life with no automatic new run',async({browser},info)=>{
 for(const kind of ['depart','RETIRE','END_LIFE']){const context=await browser.newContext({baseURL:'http://127.0.0.1:4173',viewport:{width:1440,height:900}}),p=await context.newPage();listen(p);try{let source:any;if(kind==='depart')source=feedbackExamples().actions.get('END')!.before;else{const d=driver();if(kind==='RETIRE')d.go('cave');else{d.go('sect');while(getLifeOverview(d.game).remainingMonths>1)d.doAction({type:'SOURCE',sourceId:'work',count:Math.min(50,getLifeOverview(d.game).remainingMonths-1)});}source=d.game;}const before=await load(p,source);if(kind==='depart')await ending(p,kind);else await lifeEnd(p,kind);await observe(p);const a=await begin(p,kind==='depart'?'ascension-confirm':'life-confirm-end'),after=await tick(p,a,before);expect(a.cycleMs).toBe(12000);expect(after.ending).toBe(kind==='depart'?'depart':kind==='RETIRE'?'retired':'lifespan');expect(after.core.runId).toBe(before.core.runId);expect(after.core.world.elapsedMonths-before.core.world.elapsedMonths).toBe(kind==='END_LIFE'?1:0);await expect(p.getByTestId('life-scroll')).toHaveAttribute('data-sealed','true');await expect(p.getByTestId('life-scroll-result')).toBeVisible();await clearances(p,info,kind+'-sealed');await picture(p,info,kind+'-sealed');await replayFree(p,after);await p.reload();await expect(p.getByTestId('save-status')).toHaveText('已保存');await p.getByTestId('hub-current').getByRole('button',{name:'查看生平与收卷',exact:true}).click();await expect(p.getByTestId('life-scroll')).toBeVisible();await noEffect(p);expect(await snapshot(p)).toEqual(after);expect(pageErrors.get(p)).toEqual([]);}finally{await info.attach(kind+'-console',{body:JSON.stringify({errors:pageErrors.get(p),console:consoleRows.get(p)}),contentType:'application/json'});await context.close();}}
});

test('ART05-A8 preselecting another response never borrows the original running or held saving ink and pause preserves its one exact commit',async({page},info)=>{
 const before=await load(page,tradeStory().game);await respond(page);await observe(page);const a=await begin(page);await expect(page.getByTestId('response-table')).toHaveAttribute('data-working','true');await page.clock.fastForward(3000);expect(await snapshot(page)).toEqual(before);await selectSignature(page,'story-select-decide-decline');await expect(page.getByTestId('response-table')).toHaveAttribute('data-engaged','false');await expect(page.getByTestId('response-table')).toHaveAttribute('data-state','idle');await cold(page,'response-table');await noEffect(page);await picture(page,info,'other-response-running-cold');await holdWrite(page);
 try{const left=await page.evaluate(due=>due-Date.now(),a.dueAt);await page.clock.fastForward(left);await expect(page.getByTestId('save-status')).toHaveText('保存中');expect(await page.evaluate(()=>(window as any).__narrativeHeldGame)).toEqual(before);await expect(page.getByTestId('response-table')).toHaveAttribute('data-engaged','false');await expect(page.getByTestId('response-table')).toHaveAttribute('data-state','idle');await cold(page,'response-table');await noEffect(page);await picture(page,info,'other-response-saving-cold');await page.getByTestId('training-pause').click();await expect(page.locator('[data-testid=training-activity][data-running=false]')).toBeVisible();await noEffect(page);await picture(page,info,'response-saving-pause-pending');}finally{await page.evaluate(()=>(window as any).__narrativeReleaseWrite());}
 await expect.poll(async()=>(await activity(page)).completedCycles).toBe(1);const after=await snapshot(page);expect(after).toEqual(advance(before,a.nextCommand));expect(after.choices.shen_return).toBe('bargain');await receipt(page,a,before);await page.clock.runFor(50);await noEffect(page);expect(await effects(page)).toEqual([]);await replayFree(page,after);
});

test('ART05-A9 failed acceptance keeps the original intent retryable and explicit cancellation permits only a fresh separately confirmed response',async({page},info)=>{
 const before=await load(page,tradeStory().game);await respond(page);const raw=await database(page);await observe(page);await quota(page,true);await page.getByTestId('milestone-confirm').click();await expect(page.getByTestId('milestone-retry')).toBeVisible();await expect(page.getByTestId('error')).toContainText('存储空间不足');const rejected=await page.evaluate(()=>(window as any).__narrativeRejected);expect(rejected.value.input.kind).toBe('START');expect(rejected.value.input.plan.action).toEqual({type:'DECIDE',option:'bargain'});await unchanged(page,before,null,raw);await expect(page.getByTestId('milestone-confirm')).toHaveCount(0);await expect(page.getByTestId('milestone-retry')).toBeEnabled();await picture(page,info,'response-acceptance-quota-confirmation');await page.getByTestId('milestone-cancel').click();await selectSignature(page,'story-select-decide-decline');await expect(page.getByTestId('decide-decline')).toBeEnabled();await noEffect(page);await cold(page,'response-table');await unchanged(page,before,null,raw);await picture(page,info,'cancelled-old-error-new-response');await page.getByTestId('decide-decline').click();await expect(page.getByTestId('milestone-confirm')).toBeEnabled();await expect(page.getByTestId('milestone-retry')).toHaveCount(0);const a=await begin(page);expect(rejected.value.input.mutation.commandId).toBeTruthy();expect((await database(page))['full-receipts'].some((r:any)=>r.value.input?.kind==='START'&&r.value.input.mutation.commandId!==rejected.value.input.mutation.commandId&&r.value.activity.id===a.id)).toBe(true);expect(a.plan.action).toEqual({type:'DECIDE',option:'decline'});const after=await tick(page,a,before);expect(after.choices.shen_return).toBe('decline');expect(after.core.player.stones).toBe(before.core.player.stones);expect(after.core.inventory).toEqual(before.core.inventory);const receipts=(await database(page))['full-receipts'];expect(receipts.find((r:any)=>r.key===rejected.key)).toBeUndefined();await receipt(page,a,before);await picture(page,info,'fresh-response-after-cancel');await replayFree(page,after);
});

test('ART05-A10 visit response and closing native cycle failures stay atomic then retry the same command for their first actual result only',async({browser},info)=>{
 for(const kind of ['visit','response','closing']){const context=await browser.newContext({baseURL:'http://127.0.0.1:4173',viewport:{width:1440,height:900}}),p=await context.newPage();listen(p);try{let source:any;if(kind==='visit'){const d=driver();d.go('sect');source=d.game;}else source=kind==='response'?tradeStory().game:feedbackExamples().actions.get('END')!.before;const before=await load(p,source);if(kind==='visit'){await events(p,'lu_intro');await p.getByTestId('event-lu_intro').click();}else if(kind==='response')await respond(p);else await ending(p);await observe(p);const a=await begin(p,kind==='closing'?'ascension-confirm':'milestone-confirm'),raw=await database(p);await quota(p,false);await p.clock.fastForward(a.cycleMs);await expect(p.getByTestId('error')).toContainText('存储空间不足');await unchanged(p,before,a,raw);await noEffect(p);const object=kind==='visit'?'encounter-table':'response-table';await cold(p,object);await expect(p.getByTestId(object)).toHaveAttribute('data-status','failed');await picture(p,info,kind+'-cycle-quota');if(kind==='response'){await selectSignature(p,'story-select-decide-decline');await expect(p.getByTestId('decide-decline')).toBeDisabled();await picture(p,info,'response-other-choice-quota');await selectSignature(p,'story-select-decide-bargain');}else if(kind==='visit'){await expect(p.getByTestId('event-lu_intro')).toBeDisabled();}else await expect(p.getByTestId('ending-transmit')).toBeDisabled();expect((await activity(p)).nextCommand).toEqual(a.nextCommand);await p.getByTestId('training-retry').click();await expect.poll(async()=>(await activity(p)).completedCycles).toBe(1);const after=await snapshot(p);expect(after).toEqual(advance(before,a.nextCommand));await receipt(p,a,before);await p.clock.runFor(50);await expect.poll(()=>p.locator(resultsSelector).count()).toBe(1);await clearances(p,info,kind+'-first-retry');expect(new Set((await effects(p)).map((r:any)=>r.sequence)).size).toBe(1);await picture(p,info,kind+'-same-command-first-saved');const saved=await database(p);await replayFree(p,after);expect(new Set((await effects(p)).map((r:any)=>r.sequence)).size).toBe(1);await p.reload();await expect(p.getByTestId('save-status')).toHaveText('已保存');await noEffect(p);expect(await snapshot(p)).toEqual(after);expect(await database(p)).toEqual(saved);expect(pageErrors.get(p)).toEqual([]);}finally{if(!p.isClosed())await p.evaluate(()=>{(window as any).__narrativeRestorePut?.();(window as any).__narrativeReleaseWrite?.();});await info.attach(kind+'-cycle-fault-console',{body:JSON.stringify({errors:pageErrors.get(p),console:consoleRows.get(p)}),contentType:'application/json'});await context.close();}}
});

test('ART05-A11 changing the visited person or invitation and external same-id ownership never lends or later reclaims another objects ink',async({page,context},info)=>{
 const d=driver('trade','sword');d.realm();d.funds(100);d.go('sect');const before=await load(page,d.game);await events(page,'shen_return');await page.getByTestId('event-shen_return').click();await observe(page);const a=await begin(page);await expect(page.getByTestId('encounter-table')).toHaveAttribute('data-working','true');await page.getByTestId('fate-catalogue').getByTestId('catalogue-next').click();await expect(page.getByTestId('event-pei_meet')).toBeVisible();await expect(page.getByTestId('encounter-table')).toHaveAttribute('data-engaged','false');await cold(page,'encounter-table');await noEffect(page);expect((await activity(page)).nextCommand).toEqual(a.nextCommand);await picture(page,info,'different-invitation-cold');await page.getByTestId('fate-mode-people').click();await selectPerson(page,'fate-person-lu');await cold(page,'encounter-table');const other=await context.newPage();listen(other);try{await nativeHooks(other);await useJourneyClock(other);await other.goto('/');await expect(other.getByTestId('save-status')).toHaveText('已保存');await other.getByTestId('training-resume').click();await expect.poll(async()=>(await activity(other)).generation).toBeGreaterThan(a.generation);const taken=await activity(other);expect(taken.id).toBe(a.id);expect(taken.ownerId).not.toBe(a.ownerId);expect(taken.nextCommand.commandId).not.toBe(a.nextCommand.commandId);await expect(page.locator('[data-testid=training-activity][data-generation="'+taken.generation+'"]')).toBeVisible();await cold(page,'encounter-table');expect(await snapshot(page)).toEqual(before);const after=await tick(other,taken,before);await expect.poll(async()=>(await activity(page)).completedCycles).toBe(1);expect(await snapshot(page)).toEqual(after);await selectPerson(page,'fate-person-shen');await noEffect(page);await cold(page,'encounter-table');await selectPerson(page,'fate-person-lu');await selectPerson(page,'fate-person-shen');await noEffect(page);expect(await effects(page)).toEqual([]);await picture(page,info,'foreign-visit-return-no-late-ink');await page.getByTestId('tab-2').click();await page.getByTestId('tab-3').click();await noEffect(page);await replayFree(page,after);expect(pageErrors.get(other)).toEqual([]);}finally{await other.close();}
 // An actually witnessed own result must be withdrawn immediately, not claimed again on a quick return.
 const met=await snapshot(page);await respond(page,'decline');const reply=await begin(page),replied=await tick(page,reply,met);await page.clock.fastForward(1400);await events(page,'lu_intro');await page.getByTestId('event-lu_intro').click();const own=await begin(page),visited=await tick(page,own,replied);await expect(page.getByTestId('encounter-result')).toBeVisible();const at=await page.evaluate(()=>Date.now()),count=(await effects(page)).length;await page.getByTestId('fate-mode-people').click();await selectPerson(page,'fate-person-shen');await noEffect(page);await selectPerson(page,'fate-person-lu');expect(await page.evaluate(()=>Date.now())-at).toBeLessThan(1400);await noEffect(page);expect((await effects(page)).length).toBe(count);expect(await snapshot(page)).toEqual(visited);await picture(page,info,'own-visit-quick-person-return-cold');
});

test('ART05-A12 all one hundred lawful journal rows and life-return anchors remain readable without advancing or borrowing a hidden visit',async({page},info)=>{
 const d=driver();d.go('sect');for(let i=0;i<105;i++)d.doAction({type:'SOURCE',sourceId:'work',count:1});expect(d.game.journal).toHaveLength(100);const before=await load(page,d.game),raw=await database(page);await page.getByTestId('tab-3').click();await page.getByTestId('fate-mode-journal').click();const rows=await readAll(page,'fate-catalogue');expect(rows.size).toBe(100);for(const [i,text]of [...before.journal].reverse().entries())expect(rows.get('journal-'+i)).toBe(text);await unchanged(page,before,null,raw);const last=await page.getByTestId('journal-entry').locator('p').textContent(),anchor=await page.getByTestId('journal-entry').getAttribute('data-page-key');await page.getByTestId('show-life').click();await expect(page.getByTestId('life-scroll')).toBeVisible();await picture(page,info,'hundred-journal-life-return');await page.getByTestId('hub-close').click();expect(await page.getByTestId('journal-entry').locator('p').textContent()).toBe(last);await expect(page.getByTestId('journal-entry')).toHaveAttribute('data-page-key',anchor!);await unchanged(page,before,null,raw);await events(page,'lu_intro');await page.getByTestId('event-lu_intro').click();await observe(page);const a=await begin(page);await page.getByTestId('tab-2').click();const after=await tick(page,a,before);await expect(page.getByTestId('inventory-catalogue')).toBeVisible();await page.getByTestId('tab-3').click();await page.getByTestId('fate-mode-events').click();await expect(page.getByTestId('fate-pending-meeting')).toBeVisible();await noEffect(page);await cold(page,'encounter-table');expect(await effects(page)).toEqual([]);expect(await snapshot(page)).toEqual(after);expect(after.journal).toEqual(before.journal);await picture(page,info,'hidden-visit-visible-factual-meeting');
});

test('ART05-A13 missing portraits and scene art plus both reduced-effect modes preserve complete objects real clocks and a static saved life result',async({browser},info)=>{
 for(const mode of ['system','preference']){const context=await browser.newContext({baseURL:'http://127.0.0.1:4173',viewport:{width:1440,height:900}}),p=await context.newPage();listen(p);let failedArt=0;try{await p.emulateMedia({reducedMotion:mode==='system'?'reduce':'no-preference'});await p.route('**/art/v2/**',r=>{failedArt++;return r.fulfill({status:200,contentType:'image/webp',body:'ART05 intentional image decoding failure'});});const d=driver();d.go('cave');const before=await load(p,d.game);if(mode==='preference'){await p.getByTestId('game-settings').click();await p.getByTestId('reduce-effects').check();await expect(p.locator('.app-shell')).toHaveClass(/hub-reduced/);await p.getByRole('button',{name:'关闭设置',exact:true}).click();}await p.getByTestId('tab-3').click();for(const person of getRelationships(before)){await selectPerson(p,'fate-person-'+person.id);await expect(p.getByTestId('relationship-summary-'+person.id)).toHaveText(person.summary);}await picture(p,info,mode+'-factual-art-fallback');await p.getByTestId('tab-0').click();await lifeEnd(p);await observe(p);const a=await begin(p,'life-confirm-end');await expect(p.getByTestId('life-scroll-clock')).toBeVisible();expect(await p.getByTestId('life-scroll').evaluate(n=>n.getAnimations({subtree:true}).filter(a=>a.playState==='running').map(a=>a.effect?.getTiming()))).toEqual([]);const after=await tick(p,a,before);await expect(p.getByTestId('life-scroll-result')).toBeVisible();await expect(p.locator('.narrative-object-saved')).toHaveCSS('animation-name','none');await clearances(p,info,mode+'-static-life-result');await picture(p,info,mode+'-static-life-result');expect(failedArt).toBeGreaterThan(0);expect(after.ending).toBe('retired');await receipt(p,a,before);
 const previousEffects=(await effects(p)).length;await p.getByRole('button',{name:'设置',exact:true}).click();await p.getByTestId('import').setInputFiles({name:'separate-lawful-art05-life.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(d.game))});await answerGameConfirmation(p,'import');await expect(p.getByTestId('action-execution')).toBeVisible();await finishJourneyClock(p);await expect(p.getByTestId('save-status')).toHaveText('已保存');await p.getByRole('button',{name:'关闭设置',exact:true}).click();const newLife=await snapshot(p),expected=structuredClone(d.game);expected.core.runId=newLife.core.runId;expected.core.revision=0;expect(newLife.core.runId).not.toBe(after.core.runId);expect(newLife).toEqual(expected);expect(await activity(p)).toBeNull();await noEffect(p);expect((await effects(p)).length).toBe(previousEffects);await p.clock.fastForward(120000);expect(await snapshot(p)).toEqual(newLife);await noEffect(p);expect(pageErrors.get(p)).toEqual([]);}finally{await info.attach(mode+'-art-failure-console',{body:JSON.stringify({failedArt,errors:pageErrors.get(p),console:consoleRows.get(p)}),contentType:'application/json'});await context.close();}}
});

async function syncAbort(page:Page){await page.evaluate(()=>{const w=window as any,get=IDBObjectStore.prototype.get;w.__narrativeRestoreRead=()=>IDBObjectStore.prototype.get=get;IDBObjectStore.prototype.get=function(key:any){const q=get.call(this,key);if(this.transaction.db===w.__narrativePrimaryDB&&this.transaction.mode==='readonly'&&this.name==='full-state'&&key==='current'){w.__narrativeRestoreRead();w.__narrativeSnapshotAborted=true;this.transaction.abort();}return q;};w.__narrativeSender=new BroadcastChannel('chenyuan-full-progress');w.__narrativeSender.postMessage({source:'ART05-open-review-native-snapshot-abort'});});await expect(page.getByTestId('save-status')).toHaveText('同步待核对');expect(await page.evaluate(()=>(window as any).__narrativeSnapshotAborted)).toBe(true);expect(await page.evaluate(()=>(window as any).__narrativeBC)).toBeGreaterThan(0);}

test('ART05-A14 an already open visit retirement or ascension review refuses fresh confirmation after a native sync failure until explicit reconnect and a new review',async({browser},info)=>{
 for(const kind of ['visit','retire','ending']){const context=await browser.newContext({baseURL:'http://127.0.0.1:4173',viewport:{width:1440,height:900}}),p=await context.newPage();listen(p);try{let source:any;if(kind==='ending')source=feedbackExamples().actions.get('END')!.before;else{const d=driver();d.go(kind==='retire'?'cave':'sect');source=d.game;}const before=await load(p,source),raw=await database(p),confirm=kind==='visit'?'milestone-confirm':kind==='retire'?'life-confirm-end':'ascension-confirm',cancel=kind==='visit'?'milestone-cancel':kind==='retire'?'life-cancel':'ascension-cancel';const review=async()=>{if(kind==='visit'){await events(p,'lu_intro');await p.getByTestId('event-lu_intro').click();}else if(kind==='retire')await lifeEnd(p);else await ending(p);};await review();await expect(p.getByTestId(confirm)).toBeEnabled();await syncAbort(p);await expect(p.getByTestId(confirm)).toBeDisabled();await expect(p.getByTestId(kind==='visit'?'milestone-retry':kind==='retire'?'life-retry':'ascension-retry')).toHaveCount(0);await unchanged(p,before,null,raw);await noEffect(p);await picture(p,info,kind+'-open-review-sync-error');await p.getByTestId(cancel).click();await p.getByTestId('reload-storage').click();await expect(p.getByTestId('save-status')).toHaveText('已保存');await unchanged(p,before,null,raw);await review();await expect(p.getByTestId(confirm)).toBeEnabled();await picture(p,info,kind+'-new-review-after-reconnect');await p.getByTestId(cancel).click();await unchanged(p,before,null,raw);expect(pageErrors.get(p)).toEqual([]);}finally{if(!p.isClosed())await p.evaluate(()=>{(window as any).__narrativeRestoreRead?.();(window as any).__narrativeSender?.close();});await info.attach(kind+'-open-review-errors',{body:JSON.stringify({errors:pageErrors.get(p),console:consoleRows.get(p)}),contentType:'application/json'});await context.close();}}
});

async function objectGeometry(page:Page,info:TestInfo,name:string){const g=await page.evaluate(()=>{
 const r=(n:Element)=>{const x=n.getBoundingClientRect();return{left:x.left,right:x.right,top:x.top,bottom:x.bottom,width:x.width,height:x.height};},inside=(a:any,b:any)=>a.left>=b.left-.5&&a.right<=b.right+.5&&a.top>=b.top-.5&&a.bottom<=b.bottom+.5,overlap=(a:any,b:any)=>a.left<b.right-.5&&a.right>b.left+.5&&a.top<b.bottom-.5&&a.bottom>b.top+.5,visible=(n:Element)=>!!n.getClientRects().length,ancestry='.art05-story,.narrative-object,.book-canvas,.narrative-object-paper,.response-sign-rack,.encounter-name-rack,.life-scroll-bookmarks';
 const rects=[...document.querySelectorAll<HTMLElement>('.narrative-object button,.narrative-object small,.narrative-object figcaption,.narrative-object .reading-text p,.narrative-object .choice-act strong')].filter(visible).map(n=>{const rect=r(n),parents:any[]=[];let a=n.parentElement;while(a){if(a.matches(ancestry))parents.push({class:a.className,id:a.getAttribute('data-testid'),rect:r(a),contained:inside(rect,r(a))});if(a.matches('.art05-story'))break;a=a.parentElement;}const c=getComputedStyle(n);return{text:n.textContent,id:n.getAttribute('data-testid'),tag:n.tagName,font:parseFloat(c.fontSize),rect,parents,clipped:n.scrollWidth>n.clientWidth+1||n.scrollHeight>n.clientHeight+1};});
 const racks=[...document.querySelectorAll('.encounter-name-rack,.response-sign-rack,.life-scroll-bookmarks')].filter(visible).map(n=>{const children=[...n.querySelectorAll('button')].filter(visible).map(r),clashes:any[]=[];for(let i=0;i<children.length;i++)for(let j=i+1;j<children.length;j++)if(overlap(children[i],children[j]))clashes.push({i,j,a:children[i],b:children[j]});return{class:n.className,clashes};});return{rects,racks};
 });await info.attach(name+'-object-ancestors',{body:JSON.stringify(g),contentType:'application/json'});for(const row of g.rects){expect(row.font,row.id??row.text??'').toBeGreaterThanOrEqual(row.tag==='P'||row.tag==='FIGCAPTION'||row.tag==='STRONG'?18:14);expect(row.clipped,row.id??row.text??'').toBe(false);for(const parent of row.parents)expect(parent.contained,(row.id??row.text??'')+' in '+parent.class).toBe(true);}for(const rack of g.racks)expect(rack.clashes,rack.class).toEqual([]);
}
